mapper.select:
SELECT sa.id AS Id, sa.clazz_id AS clazzId, sc.`name` AS clazzName, sa.course_id AS courseId, scs.`name` AS courseName, sa.teacher_id AS teacherId, st.`name` AS teacherName, sa.`STATUS` AS `status`, sa.sort AS sort, sa.remark AS remark FROM sys_arrange sa LEFT JOIN sys_clazz sc ON sa.clazz_id = sc.id LEFT JOIN sys_course scs ON sa.course_id = scs.id LEFT JOIN sys_teacher st ON sa.teacher_id = st.id
sa.`STATUS` = 1
AND sa.clazz_id = #{queryParams.clazzId}
AND sa.course_id = #{queryParams.courseId}
AND sa.teacher_id = #{queryParams.teacherId}

SELECT sa.id AS id, scz.grade_id AS gradeId, sg.`name` AS gradeName, sa.clazz_id AS clazzId, scz.`name` AS clazzName, sa.course_id AS courseId, sc.`name` AS courseName, sc.subject_type as subjectType, sc.full_score as fullScore, sa.teacher_id AS teacherId, st.`name` AS teacherName FROM sys_arrange sa LEFT JOIN sys_clazz scz ON sa.clazz_id = scz.id LEFT JOIN sys_grade sg ON scz.grade_id = sg.id LEFT JOIN sys_course sc ON sa.course_id = sc.id LEFT JOIN sys_teacher st ON sa.teacher_id = st.id
AND sa.clazz_id = #{queryParams.clazzId}
AND sa.course_id = #{queryParams.courseId}
AND sa.teacher_id = #{queryParams.teacherId}
